    const aoMudar = async function (ev) { const f = ev.target.closest('[data-feita]'); if (!f) return; const a = e().atividades.find(function (x) { return x.id === f.dataset.feita; }); if (f.checked) { const r = await modal({ titulo: 'Resultado', corpo: campo('O que aconteceu?', '<input name="r" placeholder="ex.: atendeu, reunião marcada para quinta 10h">') }); a.resultado = r ? r.get('r') : ''; a.feita = true; a.feitaEm = new Date().toISOString(); const c = conta(a.contaId); if (c) linhaTempo(c, a.tipo, a.titulo + (a.resultado ? ': ' + a.resultado : '')); } else a.feita = false; salvar(); App.redesenhar(); };
    const aoClicar = function (ev) { const b = ev.target.closest('[data-msg]'); if (!b) return; const a = e().atividades.find(function (x) { return x.id === b.dataset.msg; }); const c = conta(a.contaId); const sc = e().scripts.filter(function (s) { return s.canal === a.tipo; }); escreverMensagem(c, sc[0]); };
